const $=id=>document.getElementById(id),B=(en,hi)=>({en,hi}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),STORE='vigyan-darshan-v3';let shared={};try{shared=JSON.parse(localStorage.getItem(STORE)||'{}')}catch{}
let prefs={language:['bi','en','hi'].includes(shared.language)?shared.language:'bi',theme:shared.theme||'system',fontSize:[15,17,19].includes(shared.fontSize)?shared.fontSize:17,lowPower:shared.lowPower??(navigator.hardwareConcurrency||4)<=2};let progress={selectedClass:'LKG',lastByClass:{},complete:[],best:{},mistakes:{},...shared.earlyYears};if(!Array.isArray(progress.complete))progress.complete=[];for(let k of['lastByClass','best','mistakes'])if(!progress[k]||typeof progress[k]!=='object')progress[k]={};
let course=null,classId='LKG',subjectId='english',lesson=null,tab='explore',cardIndex=0,counted=new Set,seen=new Set,attempts={},questionIndex=0,showMistakes=false,board=null,loadToken=0,classes=[],arithmetic={a:3,b:2,op:'add'};
const text=b=>typeof b==='string'?b:(prefs.language==='en'?b?.en:b?.hi)||b?.en||'',dual=b=>typeof b==='string'?b:prefs.language==='en'?b.en:prefs.language==='hi'?b.hi:b.en===b.hi?b.en:b.en+' | '+b.hi;
const label=(en,hi)=>en===hi?esc(en):`<span class="en">${esc(en)}</span><span class="sep"> | </span><span class="hi">${esc(hi)}</span>`;
const H=(b,n=2)=>`<h${n} class="heading"><span class="en">${esc(b.en)}</span><span class="hi">${esc(b.hi)}</span></h${n}>`,P=b=>`<p>${esc(text(b))}</p>`;
function save(){try{let fresh={};try{const stored=JSON.parse(localStorage.getItem(STORE)||'{}');if(stored&&typeof stored==='object'&&!Array.isArray(stored))fresh=stored}catch{}localStorage.setItem(STORE,JSON.stringify({...fresh,...prefs,selectedClass:classId,earlyYears:progress}))}catch{$('offline').textContent=text(B('Progress cannot be saved on this device right now.','अभी इस उपकरण पर प्रगति सुरक्षित नहीं हो पा रही।'))}}
function stopSpeech(){if('speechSynthesis'in window)speechSynthesis.cancel()}
function apply(){document.documentElement.dataset.language=prefs.language;document.documentElement.lang=prefs.language==='en'?'en':'hi';document.documentElement.dataset.theme=prefs.theme;document.documentElement.style.fontSize=prefs.fontSize+'px';document.documentElement.dataset.lowPower=String(prefs.lowPower);$('language').value=prefs.language;$('lowPower').checked=prefs.lowPower;const dark=prefs.theme==='dark'||prefs.theme==='system'&&matchMedia('(prefers-color-scheme:dark)').matches;$('theme').textContent=dark?'☀':'🌙';$('courseBadge').innerHTML=label(`Class ${classId} · Little Learners`,`कक्षा ${classId} · नन्हे शिक्षार्थी`);$('home').innerHTML=label('Learning home','सीखने का घर');$('print').innerHTML=label('Print revision card','दोहराव कार्ड प्रिंट करें');$('previous').innerHTML=label('← Previous lesson','← पिछला पाठ');$('next').innerHTML=label('Next lesson →','अगला पाठ →');if('serviceWorker'in navigator&&isSecureContext)$('offline').textContent=text(B('An offline copy is prepared after the first complete download.','पहली पूरी डाउनलोडिंग के बाद ऑफलाइन प्रति तैयार होती है।'));$('search').placeholder=dual(B('Search this subject…','इस विषय में खोजें…'));$('basis').textContent=text(B('Original play-based LKG/UKG companion inspired by foundational-stage learning. Explore a little at a time with an adult; this is not a prescribed NCERT chapter list.','बुनियादी-स्तर की सीख से प्रेरित मौलिक खेल-आधारित LKG/UKG साथी। किसी बड़े के साथ थोड़ा-थोड़ा खोजें; यह निर्धारित NCERT अध्याय सूची नहीं है।'));document.title=`Little Learners / नन्हे शिक्षार्थी · ${classId}`;for(let b of document.querySelectorAll('[data-font]'))b.setAttribute('aria-pressed',String(+b.dataset.font===prefs.fontSize));renderNav()}
function allLessons(){return course?.subjects.flatMap(s=>s.lessons)||[]}
function subject(){return course?.subjects.find(s=>s.id===subjectId)||course?.subjects[0]}
function updateUrl(home=false){let u=new URL(location.href);u.search='';u.searchParams.set('class',classId);if(!home)u.searchParams.set('subject',subjectId);u.hash=lesson&&!home?lesson.id:'';history.replaceState(null,'',u.pathname+u.search+u.hash)}
function olderLink(id){if(subjectId==='hindi')return`index.html?class=${id}&subject=hindi`;if(subjectId==='math')return`../math/index.html#class-${id}/0`;if(subjectId==='english'||subjectId==='art')return`../${subjectId}/index.html?class=${id}`;return`../science.html#class-${id}`}
function renderNav(){$('classNav').innerHTML=['LKG','UKG',...Array.from({length:12},(_,i)=>String(i+1))].map(id=>grades.includes(id)?`<button data-class="${id}" aria-pressed="${classId===id}">${id}</button>`:`<a href="${olderLink(id)}" ${classId===id?'aria-current="page"':''}>${id}</a>`).join('');$('subjectNav').innerHTML=Object.entries(subjectMap).map(([id,s])=>`<button data-subject="${id}" aria-pressed="${subjectId===id}"><span class="subjectEmoji" aria-hidden="true">${s.icon}</span><span>${label(s.en,s.hi)}</span></button>`).join('');for(let b of $('classNav').querySelectorAll('[data-class]'))b.onclick=()=>openClass(b.dataset.class);for(let b of $('subjectNav').querySelectorAll('[data-subject]'))b.onclick=()=>{if(!course){subjectId=b.dataset.subject;openClass(grades.includes(classId)?classId:'LKG',subjectId);return}subjectId=b.dataset.subject;const found=subject().lessons.find(l=>l.id===progress.lastByClass[classId]);selectLesson((found||subject().lessons[0]).id)};}
function sidebar(){const items=subject()?.lessons||[],q=$('search').value.toLocaleLowerCase();$('lessonList').innerHTML=items.filter(l=>(l.title.en+' '+l.title.hi).toLocaleLowerCase().includes(q)).map((l,i)=>`<button class="lessonLink ${lesson?.id===l.id?'active':''}" data-lesson="${esc(l.id)}" ${lesson?.id===l.id?'aria-current="page"':''}><span class="lessonNum">${String(items.indexOf(l)+1).padStart(2,'0')}</span><span class="lessonNames">${label(l.title.en,l.title.hi)}${progress.best[l.id]!==undefined?`<small>${label('Best','श्रेष्ठ')}: ${progress.best[l.id]}/10</small>`:''}</span><span class="lessonTick" aria-label="${progress.complete.includes(l.id)?'Lesson explored | पाठ पूरा':'Not finished | अभी अधूरा'}">${progress.complete.includes(l.id)?'★':'☆'}</span></button>`).join('')||P(B('No matching lesson. Try a different word.','यह पाठ नहीं मिला। दूसरा शब्द खोजें।'));const done=allLessons().filter(l=>progress.complete.includes(l.id)).length;$('progress').max=allLessons().length||20;$('progress').value=done;$('progressText').textContent=dual(B(`${done} / ${allLessons().length} lessons explored`,`${done} / ${allLessons().length} पाठ पूरे`))}
function showHome(){if(!course){openClass(grades.includes(classId)?classId:'LKG',subjectId);return}board?.destroy();board=null;stopSpeech();lesson=null;tab='explore';$('lesson').hidden=true;$('welcome').hidden=false;updateUrl(true);sidebar();const last=allLessons().find(l=>l.id===progress.lastByClass[classId]);$('welcome').innerHTML=`<article class="welcomeHero"><div>${H(B('Little steps. Big discoveries.','छोटे कदम। नई खोजें।'),1)}${P(B('Look, say, count and create. Choose something you want to explore today.','देखें, बोलें, गिनें और बनाएँ। आज जो सीखना अच्छा लगे, उसे चुनें।'))}<p>${label('Class '+classId+' · 5 subjects · 20 lessons','कक्षा '+classId+' · 5 विषय · 20 पाठ')}</p></div><img class="owl" src="owl.svg" alt="" width="150" height="170"></article>`+(last?`<article class="kidCard">${H(B('Continue your little adventure','अपनी सीख जारी रखें'))}${H(last.title,3)}<button class="primary" data-lesson="${last.id}">${label('Continue learning →','पढ़ना जारी रखें →')}</button></article>`:'')+H(B('What shall we explore?','आज क्या सीखें?'))+`<div class="subjectGridEarly">${course.subjects.map(s=>`<button class="kidCard" data-open-subject="${s.id}"><span class="bigEmoji" aria-hidden="true">${s.icon}</span>${H(s.title,3)}${P(B(`${s.lessons.length} playful lessons`,`${s.lessons.length} खेल-आधारित पाठ`))}</button>`).join('')}</div><article class="kidCard">${H(B('For the grown-up beside you','साथ बैठे बड़े के लिए'),3)}${P(B('Read together, ask what the child notices and let them try again. These activities are not a timed exam. Paper, conversation and real objects can extend the same idea away from the screen.','साथ पढ़ें, पूछें कि बच्चे ने क्या देखा और उसे फिर कोशिश करने दें। ये गतिविधियाँ समयबद्ध परीक्षा नहीं हैं। कागज, बातचीत और असली वस्तुओं से यही बात स्क्रीन से दूर भी समझ सकते हैं।'))}</article>`;for(let b of $('welcome').querySelectorAll('[data-open-subject]'))b.onclick=()=>{subjectId=b.dataset.openSubject;selectLesson(subject().lessons[0].id)}}
async function openClass(id,requestedSubject=null,requestedLesson=null){const token=++loadToken;board?.destroy();board=null;stopSpeech();if($('lessonDrawer').open)$('lessonDrawer').close();classId=String(id);subjectId=requestedSubject&&subjectMap[requestedSubject]?requestedSubject:subjectId;lesson=null;course=null;$('search').value='';$('lesson').hidden=true;$('welcome').hidden=false;$('welcome').innerHTML=P(B('Opening your learning cards…','आपके सीखने वाले कार्ड खुल रहे हैं…'));apply();sidebar();if(!grades.includes(classId)){$('welcome').innerHTML=H(B(`Class ${classId} Hindi`,`कक्षा ${classId} हिंदी`),1)+`<article class="kidCard">${H(B('Coming soon','जल्द आ रहा है'))}${P(B('Hindi lessons for this class are not available yet. Choose LKG or UKG to explore the new learning cards.','इस कक्षा के हिंदी पाठ अभी उपलब्ध नहीं हैं। नए कार्ड पढ़ने के लिए LKG या UKG चुनें।'))}</article>`;return}try{const meta=classes.find(c=>c.id===classId),r=await fetch('data/'+meta.file);if(!r.ok)throw Error('Unavailable class');const data=await r.json();if(token!==loadToken)return;course=data;progress.selectedClass=classId;save();apply();sidebar();if(requestedLesson&&allLessons().some(l=>l.id===requestedLesson))selectLesson(requestedLesson);else if(requestedSubject)selectLesson(subject().lessons[0].id);else showHome()}catch(e){if(token!==loadToken)return;$('welcome').innerHTML=H(B('Could not open this class','कक्षा नहीं खुल सकी'),1)+P(B('Reconnect and try opening the class again.','इंटरनेट जोड़कर कक्षा फिर खोलें।'));console.error(e)}}
function selectLesson(id){const found=allLessons().find(l=>l.id===id);if(!found)return;board?.destroy();board=null;stopSpeech();lesson=found;subjectId=lesson.subject;progress.lastByClass[classId]=id;save();cardIndex=0;counted=new Set;seen=new Set([0]);attempts={};questionIndex=0;showMistakes=false;arithmetic={a:3,b:2,op:'add'};tab='explore';if($('lessonDrawer').open)$('lessonDrawer').close();$('welcome').hidden=true;$('lesson').hidden=false;updateUrl();apply();sidebar();renderLesson();$('lessonTitle').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}
function renderLesson(){$('lessonMeta').textContent=dual(B(`${classId} · ${subjectMap[subjectId].en} · Lesson ${subject().lessons.indexOf(lesson)+1} / 4`,`${classId} · ${subjectMap[subjectId].hi} · पाठ ${subject().lessons.indexOf(lesson)+1} / 4`));$('lessonTitle').innerHTML=`<span class="en">${esc(lesson.title.en)}</span><span class="hi">${esc(lesson.title.hi)}</span>`;$('goal').textContent=text(lesson.goal);const done=progress.complete.includes(lesson.id);$('finish').innerHTML=label(done?'★ Lesson explored':'☆ Finish this lesson',done?'★ पाठ पूरा':'☆ पाठ पूरा करें');$('finish').setAttribute('aria-pressed',String(done));$('previous').disabled=subject().lessons[0].id===lesson.id;$('next').disabled=subject().lessons.at(-1).id===lesson.id;renderTabs();renderExplore();renderNotes();renderPractice();renderRevision();if(tab==='draw'||board)renderDrawing()}
const TABS=[['explore','Look & Listen','देखें और सुनें'],['notes','Simple Notes','आसान बातें'],['practice','Play & Practice','खेल और अभ्यास'],['draw','Draw & Trace','बनाएँ और लिखें'],['revision','Revision Card','दोहराव कार्ड']];
function renderTabs(){$('tabs').innerHTML=TABS.map(([id,en,hi])=>`<button id="tab-${id}" role="tab" aria-controls="${id}" aria-selected="${id===tab}" tabindex="${id===tab?0:-1}">${label(en,hi)}</button>`).join('');for(let[id]of TABS){$(id).hidden=id!==tab;$(id).setAttribute('aria-labelledby','tab-'+id);$('tab-'+id).onclick=()=>switchTab(id);$('tab-'+id).onkeydown=e=>{let index=TABS.findIndex(t=>t[0]===id),next;if(e.key==='ArrowRight')next=(index+1)%5;if(e.key==='ArrowLeft')next=(index+4)%5;if(e.key==='Home')next=0;if(e.key==='End')next=4;if(next!==undefined){e.preventDefault();switchTab(TABS[next][0]);$('tab-'+TABS[next][0]).focus()}}}}
function switchTab(id){stopSpeech();tab=id;renderTabs();if(id==='draw'&&!board)renderDrawing()}
function artFor(card){if(card.position)return positionSvg(card.position);if(card.groups)return comparisonSvg(card.groups);if(card.picture==='●'&&card.count===undefined)return '';if(card.count!==undefined){if(card.count===0)return P(B('No dots yet.','अभी कोई बिंदु नहीं।'));let index=0;return`<div class="countFrames">${countGroups(card.count).map(n=>`<div class="tenFrame">${Array.from({length:10},(_,j)=>j<n?`<button class="dotButton" data-dot="${index}" aria-label="${dual(B('Count dot '+(index+1),'बिंदु '+(index+1)+' गिनें'))}" aria-pressed="${counted.has(index++)}"><span class="dot" aria-hidden="true"></span></button>`:'<span class="emptyCell" aria-hidden="true"></span>').join('')}</div>`).join('')}</div><p class="countStatus" id="countStatus" role="status">${counted.size} / ${card.count} ${label('counted','गिने')}</p>`}if(card.shape)return shapeSvg(card.shape,card.color);return`<div class="bigPicture" aria-hidden="true">${esc(card.picture||'⭐')}</div>`}
function renderExplore(){const card=lesson.cards[cardIndex];$('explore').innerHTML=`<div class="exploreGrid"><article class="learningBoard">${H(B('Look. Say. Try.','देखें। बोलें। करें।'))}<div class="pictureStage ${prefs.lowPower?'':'pop'}">${card.symbol?`<div class="bigSymbol">${esc(card.symbol)}</div>`:''}${artFor(card)}${H(card.label,3)}</div><div class="cardControls"><button id="prevCard" ${cardIndex===0?'disabled':''}>${label('← Previous','← पिछला')}</button><strong>${cardIndex+1} / ${lesson.cards.length}</strong><button id="nextCard" ${cardIndex===lesson.cards.length-1?'disabled':''}>${label('Next →','अगला →')}</button></div><div class="audioButtons"><button id="listenEn">${label('🔊 English','🔊 अंग्रेज़ी')}</button><button id="listenHi">${label('🔊 Hindi','🔊 हिंदी')}</button></div><p class="audioNote">${text(B('Listening uses an installed local voice if available. You can always read together.','उपलब्ध हो तो उपकरण की स्थानीय आवाज़ से सुनें। साथ पढ़ना हमेशा संभव है।'))}</p><p id="audioStatus" class="audioNote" role="status"></p><div class="cardRail" aria-label="${dual(B('Choose a card','कार्ड चुनें'))}">${lesson.cards.map((c,i)=>`<button data-card="${i}" aria-pressed="${cardIndex===i}" aria-label="${esc(dual(c.label))}"><span class="miniEmoji" aria-hidden="true">${esc(c.picture||'⭐')}</span>${esc(c.symbol||String(i+1))}</button>`).join('')}</div><p class="status" id="exploreStatus">${dual(B(`${seen.size} / ${lesson.cards.length} cards explored`,`${seen.size} / ${lesson.cards.length} कार्ड देखे`))}</p></article><div>${lesson.activity?.type==='arithmetic'?arithmeticHTML():''}<article class="kidCard">${H(B('Let’s play together','आओ साथ खेलें'),3)}${lesson.play.map(p=>`<div class="playPrompt">${P(p)}</div>`).join('')}<button id="goPractice" class="primary">${label(subjectId==='art'?'Try the drawing':'Play a question',subjectId==='art'?'चित्र बनाएँ':'प्रश्न खेलें')}</button></article><article class="kidCard">${H(B('Your little mission','आपकी छोटी कोशिश'),3)}${P(B('Explore 3 different cards. Tell someone one thing you noticed.','3 अलग कार्ड देखें। किसी को अपनी देखी हुई 1 बात बताएँ।'))}<p>${seen.size>=3?'✓ ':''}${dual(B(`${Math.min(seen.size,3)} / 3 cards`,`${Math.min(seen.size,3)} / 3 कार्ड`))}</p></article></div></div>`;$('prevCard').onclick=()=>changeCard(cardIndex-1);$('nextCard').onclick=()=>changeCard(cardIndex+1);for(let b of $('explore').querySelectorAll('[data-card]'))b.onclick=()=>changeCard(+b.dataset.card);for(let b of $('explore').querySelectorAll('[data-dot]'))b.onclick=()=>{const index=+b.dataset.dot;if(counted.has(index))counted.delete(index);else counted.add(index);b.setAttribute('aria-pressed',String(counted.has(index)));$('countStatus').innerHTML=`${counted.size} / ${card.count} ${label('counted','गिने')}`};$('listenEn').onclick=()=>speak('en',card);$('listenHi').onclick=()=>speak('hi',card);$('goPractice').onclick=()=>switchTab(subjectId==='art'?'draw':'practice');if(lesson.activity?.type==='arithmetic')wireArithmetic()}
function arithmeticHTML(){return `<article class="kidCard">${H(B('Try your own numbers','अपने अंक आज़माएँ'),3)}<label for="arithOp">${label('Choose an action','क्रिया चुनें')}</label><select id="arithOp"><option value="add" ${arithmetic.op==='add'?'selected':''}>${esc(dual(B('Put together','जोड़ें')))}</option><option value="subtract" ${arithmetic.op==='subtract'?'selected':''}>${esc(dual(B('Take away','घटाएँ')))}</option></select><div class="mathControl"><label for="amountA">${label('Start with','शुरू में')} <output id="outA">${arithmetic.a}</output></label><input id="amountA" type="range" min="0" max="${arithmetic.op==='add'?5:10}" step="1" value="${arithmetic.a}"></div><div class="mathControl"><label for="amountB">${label('How many more / away?','कितने और / कम?')} <output id="outB">${arithmetic.b}</output></label><input id="amountB" type="range" min="0" max="${arithmetic.op==='add'?5:arithmetic.a}" step="1" value="${arithmetic.b}"></div><div id="arithmeticResult" class="mathResult" role="status"></div></article>`}
function wireArithmetic(){const draw=()=>{const result=arithmeticResult(arithmetic.a,arithmetic.b,arithmetic.op);$('amountA').max=arithmetic.op==='add'?5:10;$('amountB').max=arithmetic.op==='add'?5:arithmetic.a;$('amountA').value=arithmetic.a;$('amountB').value=arithmetic.b;$('outA').textContent=arithmetic.a;$('outB').textContent=arithmetic.b;$('arithmeticResult').innerHTML=`<p><strong>${arithmetic.a} ${arithmetic.op==='add'?'+':'−'} ${arithmetic.b} = ${result}</strong></p><div aria-hidden="true">${Array.from({length:result},()=>'<span>●</span>').join('')}</div>${result===0?P(B('No objects remain.','कोई वस्तु नहीं बची।')):''}`};$('arithOp').onchange=e=>{arithmetic.op=e.target.value;arithmetic.a=Math.min(arithmetic.a,arithmetic.op==='add'?5:10);arithmetic.b=Math.min(arithmetic.b,arithmetic.op==='add'?5:arithmetic.a);draw()};$('amountA').oninput=e=>{arithmetic.a=+e.target.value;if(arithmetic.op==='subtract')arithmetic.b=Math.min(arithmetic.b,arithmetic.a);draw()};$('amountB').oninput=e=>{arithmetic.b=+e.target.value;draw()};draw()}
function changeCard(i){if(i<0||i>=lesson.cards.length)return;stopSpeech();cardIndex=i;seen.add(i);counted=new Set;renderExplore()}
function speak(lang,card){if(!('speechSynthesis'in window)){$('audioStatus').textContent=text(B('No voice is available here. Read this card together.','यहाँ आवाज़ उपलब्ध नहीं है। कार्ड साथ पढ़ें।'));return}const voice=speechSynthesis.getVoices().find(v=>v.localService&&v.lang.toLowerCase().startsWith(lang));if(!voice){$('audioStatus').textContent=text(B('A local voice for this language is unavailable right now. Read the card together.','इस समय इस भाषा की स्थानीय आवाज़ उपलब्ध नहीं है। कार्ड साथ पढ़ें।'));return}stopSpeech();const u=new SpeechSynthesisUtterance(card.say?.[lang]||card.label[lang]);u.voice=voice;u.lang=lang==='hi'?'hi-IN':'en-IN';u.rate=.8;u.onerror=()=>{if($('audioStatus'))$('audioStatus').textContent=text(B('Listening is unavailable. Let’s read together.','अभी सुनना संभव नहीं। साथ पढ़ें।'))};speechSynthesis.speak(u);$('audioStatus').textContent=text(B('Listening…','सुन रहे हैं…'))}
function renderNotes(){$('notes').innerHTML=H(B('Simple Notes','आसान बातें'))+lesson.notes.map(n=>`<article class="kidCard">${H(n.title,3)}${P(n.body)}</article>`).join('')}
function optionReason(q,i){return i===q.correct?text(q.reason):text(B(`This choice is “${q.options[i].en}”. We need “${q.options[q.correct].en}”. ${q.reason.en}`,`यह विकल्प “${q.options[i].hi}” है। हमें “${q.options[q.correct].hi}” चाहिए। ${q.reason.hi}`))}
function renderPractice(){if(subjectId==='art'){$('practice').innerHTML=H(B('Look and talk','देखें और बताएं'))+`<article class="kidCard">${lesson.observations.map((q,i)=>`<div class="observation">${H(B('Notice '+(i+1),'देखें '+(i+1)),3)}${P(q.question)}<details><summary>${label('Talk about it','इस पर बात करें')}</summary>${P(q.answer)}</details></div>`).join('')}<button id="artDraw" class="primary">${label('Open drawing board','चित्र पट खोलें')}</button></article>`;$('artDraw').onclick=()=>switchTab('draw');return}
const mistakes=Object.keys(progress.mistakes).filter(k=>k.startsWith(lesson.id+':'));$('practice').innerHTML=H(B('Play & Practice','खेल और अभ्यास'))+`<nav class="practiceSubnav"><button id="questionsTab" aria-pressed="${!showMistakes}">${label('Questions','प्रश्न')}</button><button id="againTab" aria-pressed="${showMistakes}">${label('Let’s try again','फिर से सीखें')} (${mistakes.length})</button></nav><div id="practiceBody"></div>`;$('questionsTab').onclick=()=>{showMistakes=false;renderPractice()};$('againTab').onclick=()=>{showMistakes=true;renderPractice()};if(showMistakes){$('practiceBody').innerHTML=mistakes.length?mistakes.map(k=>{let q=lesson.quiz[progress.mistakes[k]];return`<article class="kidCard">${P(q.question)}<p><strong>${esc(dual(q.options[q.correct]))}</strong></p>${P(q.reason)}<button data-review="${esc(k)}">${label('I understand','समझ गया')}</button></article>`}).join(''):`<article class="kidCard">${P(B('Nothing saved for another try. Keep exploring!','फिर सीखने के लिए अभी कोई प्रश्न नहीं है। खोज जारी रखें!'))}</article>`;for(let b of $('practiceBody').querySelectorAll('[data-review]'))b.onclick=()=>{delete progress.mistakes[b.dataset.review];save();renderPractice()};return}
if(questionIndex>=lesson.quiz.length){const score=firstTryScore(attempts),best=Math.max(progress.best[lesson.id]||0,score);progress.best[lesson.id]=best;save();sidebar();$('practiceBody').innerHTML=`<article class="kidCard">${H(B('You kept trying!','आपने कोशिश जारी रखी!'))}<div class="scoreStars" aria-hidden="true">★★★</div>${P(B(`First tries: ${score} / 10. Best: ${best} / 10.`,`पहली कोशिश: ${score} / 10। श्रेष्ठ: ${best} / 10।`))}<p>${text(B('Every practice helps. You can play again whenever you want.','हर अभ्यास मदद करता है। जब मन हो, फिर खेलें।'))}</p><button id="retryQuiz">${label('Play again','फिर खेलें')}</button></article>`;$('retryQuiz').onclick=()=>{attempts={};questionIndex=0;renderPractice()};return}
const q=lesson.quiz[questionIndex],a=attempts[questionIndex];$('practiceBody').innerHTML=`<article class="kidCard"><p class="eyebrow">${label('Question','प्रश्न')} ${questionIndex+1} / 10</p>${H(q.question,3)}<div class="quizChoices">${q.options.map((o,i)=>`<button data-answer="${i}" ${a?.solved?'disabled':''} class="quizChoice ${a?.selected===i?(a.solved&&i===q.correct?'correct':'retry'):''}">${label(o.en,o.hi)}${a?`<span class="choiceReason">${esc(optionReason(q,i))}</span>`:''}</button>`).join('')}</div>${a?`<div class="feedback ${a.solved?'':'again'}" role="status">${a.solved?label('✓ You found it!','✓ आपने ढूँढ लिया!'):label('Let’s look once more.','एक बार फिर देखें।')}${P(q.reason)}</div>`:''}<div class="questionActions"><button id="nextQuestion" ${!a?.solved?'disabled':''}>${label(questionIndex===9?'Finish practice':'Next question →',questionIndex===9?'अभ्यास पूरा':'अगला प्रश्न →')}</button><button id="resetPractice">${label('Start again','फिर शुरू करें')}</button></div></article>`;for(let b of $('practiceBody').querySelectorAll('[data-answer]'))b.onclick=()=>{const choice=+b.dataset.answer;attempts=recordAnswer(attempts,questionIndex,choice,q.correct);if(choice!==q.correct)progress.mistakes[lesson.id+':'+questionIndex]=questionIndex;save();renderPractice()};$('nextQuestion').onclick=()=>{questionIndex++;renderPractice()};$('resetPractice').onclick=()=>{attempts={};questionIndex=0;renderPractice()}}
function renderDrawing(){const kept=board?{items:board.items,color:board.color,tool:board.tool,cursor:board.cursor,showGuide:board.showGuide}:null;board?.destroy();$('draw').innerHTML=H(B('Draw & Trace','बनाएँ और लिखें'))+`<article class="kidCard">${P(B('Make your own marks. The faint guide is a visual aid, not a stroke-order test.','अपने निशान बनाएँ। हल्की रूपरेखा केवल मदद है, लिखने के क्रम की परीक्षा नहीं।'))}<div class="drawingTools"><label>${label('Tool','औज़ार')} <select id="drawTool"><option value="brush">${esc(dual(B('Brush','ब्रश')))}</option><option value="circle">${esc(dual(B('Circle','वृत्त')))}</option><option value="square">${esc(dual(B('Square','वर्ग')))}</option><option value="triangle">${esc(dual(B('Triangle','त्रिभुज')))}</option></select></label><label><input id="showGuide" type="checkbox" checked> ${label('Show guide','रूपरेखा दिखाएँ')}</label><button id="stamp">${label('Add a shape','आकृति जोड़ें')}</button></div><div class="palette" aria-label="${dual(B('Choose a colour','रंग चुनें'))}">${[['#235a45','Green','हरा'],['#bf4439','Red','लाल'],['#3c69a9','Blue','नीला'],['#e8bd42','Yellow','पीला'],['#8359a3','Purple','बैंगनी'],['#d87a36','Orange','नारंगी'],['#24302b','Dark','गहरा']].map(([color,en,hi],i)=>`<button data-color="${color}" aria-label="${en} | ${hi}" aria-pressed="${i===0}"><span style="background:${color}" aria-hidden="true"></span></button>`).join('')}</div><canvas id="drawingCanvas" class="drawCanvas" width="800" height="500" tabindex="0" role="img" aria-label="Drawing board. Draw with a finger or mouse. Arrow keys move the pen, Space raises or lowers it; Enter adds a shape. | चित्र पट। उँगली या माउस से बनाएँ। तीर कलम खिसकाते हैं, Space उठाता या रखता है, Enter आकृति जोड़ता है।"></canvas><div class="drawingTools"><button id="undoDraw">${label('↶ Undo','↶ पिछला हटाएँ')}</button><button id="clearDraw">${label('Clear board','पट साफ करें')}</button><button id="downloadDraw" class="primary">${label('Save PNG','PNG सुरक्षित करें')}</button></div><p id="drawingStatus" role="status"></p><details class="drawHelp"><summary>${label('Keyboard help','कीबोर्ड से मदद')}</summary>${P(B('Focus the board. Arrow keys move the pen; hold Shift for smaller steps. Space switches the pen up/down. Enter adds the chosen shape. Drawings stay in this open lesson; save a PNG to keep one.','पट चुनें। तीर से कलम चलाएँ; छोटे कदम के लिए Shift रखें। Space से कलम उठाएँ या रखें। Enter चुनी आकृति जोड़ता है। चित्र इसी खुले पाठ में रहते हैं; रखने के लिए PNG सुरक्षित करें।'))}</details></article>`;board=new DrawBoard($('drawingCanvas'),{guide:lesson.guide||'lines',trace:lesson.trace||'',onStatus:s=>{$('drawingStatus').textContent=s==='pen-down'?text(B('Pen down. Move with the arrows.','कलम रखी है। तीर से चलाएँ।')):s==='pen-up'?text(B('Pen up.','कलम उठी है।')):text(B('Keep creating. Save a PNG if you want to keep your drawing.','बनाते रहें। चित्र रखना हो तो PNG सुरक्षित करें।'))}});if(kept){Object.assign(board,kept);board.paint();$('drawTool').value=board.tool;$('showGuide').checked=board.showGuide;for(let b of $('draw').querySelectorAll('[data-color]'))b.setAttribute('aria-pressed',String(b.dataset.color===board.color))}$('drawTool').onchange=e=>board.tool=e.target.value;$('showGuide').onchange=e=>{board.showGuide=e.target.checked;board.paint()};for(let b of $('draw').querySelectorAll('[data-color]'))b.onclick=()=>{board.color=b.dataset.color;for(let v of $('draw').querySelectorAll('[data-color]'))v.setAttribute('aria-pressed',String(v===b))};$('stamp').onclick=()=>{board.stamp();board.paint()};$('undoDraw').onclick=()=>board.undo();$('clearDraw').onclick=()=>board.clear();$('downloadDraw').onclick=()=>board.download()}
function renderRevision(){$('revision').innerHTML=H(B('Revision Card','दोहराव कार्ड'))+`<article class="kidCard">${H(lesson.title,3)}${P(lesson.goal)}<div class="revisionCards">${lesson.cards.map(c=>`<div class="revisionMini"><span class="symbol">${esc(c.symbol||c.picture)}</span><p>${esc(dual(c.label))}</p></div>`).join('')}</div><ul>${lesson.play.map(p=>`<li>${esc(text(p))}</li>`).join('')}</ul></article>`}
$('lessonList').onclick=e=>{let b=e.target.closest('[data-lesson]');if(b)selectLesson(b.dataset.lesson)};$('welcome').onclick=e=>{let b=e.target.closest('[data-lesson]');if(b)selectLesson(b.dataset.lesson)};$('home').onclick=showHome;$('search').oninput=sidebar;$('finish').onclick=()=>{const index=progress.complete.indexOf(lesson.id);if(index<0)progress.complete.push(lesson.id);else progress.complete.splice(index,1);save();sidebar();const done=progress.complete.includes(lesson.id);$('finish').innerHTML=label(done?'★ Lesson explored':'☆ Finish this lesson',done?'★ पाठ पूरा':'☆ पाठ पूरा करें');$('finish').setAttribute('aria-pressed',String(done))};$('previous').onclick=()=>selectLesson(subject().lessons[subject().lessons.indexOf(lesson)-1].id);$('next').onclick=()=>selectLesson(subject().lessons[subject().lessons.indexOf(lesson)+1].id);$('print').onclick=()=>{renderRevision();window.print()};$('language').onchange=e=>{prefs.language=e.target.value;stopSpeech();save();apply();sidebar();if(lesson)renderLesson();else if(course)showHome()};$('theme').onclick=()=>{const dark=prefs.theme==='dark'||prefs.theme==='system'&&matchMedia('(prefers-color-scheme:dark)').matches;prefs.theme=dark?'light':'dark';save();apply()};$('settings').onclick=()=>{$('settingsPanel').hidden=!$('settingsPanel').hidden;$('settings').setAttribute('aria-expanded',String(!$('settingsPanel').hidden))};for(let b of document.querySelectorAll('[data-font]'))b.onclick=()=>{prefs.fontSize=+b.dataset.font;save();apply()};$('lowPower').onchange=e=>{prefs.lowPower=e.target.checked;save();apply()};$('menu').onclick=()=>{$('drawerMount').append($('sidebarContent'));$('lessonDrawer').showModal();$('menu').setAttribute('aria-expanded','true')};$('closeDrawer').onclick=()=>$('lessonDrawer').close();$('lessonDrawer').addEventListener('close',()=>{$('sidebar').append($('sidebarContent'));$('menu').setAttribute('aria-expanded','false')});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('settingsPanel').hidden=true;$('settings').setAttribute('aria-expanded','false')}});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSpeech()});window.addEventListener('pagehide',()=>{stopSpeech();board?.destroy()});window.addEventListener('resize',()=>{if(innerWidth>=768&&$('lessonDrawer').open)$('lessonDrawer').close()});
try{const r=await fetch('data/classes.json');if(!r.ok)throw Error('Class list unavailable');classes=await r.json();const url=new URL(location.href),cls=url.searchParams.get('class')||progress.selectedClass||'LKG',sub=url.searchParams.get('subject');await openClass(cls,sub,location.hash.slice(1)||null)}catch(e){$('welcome').innerHTML=H(B('Could not open learning cards','कार्ड नहीं खुल सके'),1)+P(B('Reconnect and reload this page.','इंटरनेट जोड़कर यह पृष्ठ फिर खोलें।'));console.error(e)}if('serviceWorker'in navigator&&isSecureContext)navigator.serviceWorker.register('../sw.js').then(()=>{$('offline').textContent=text(B('An offline copy is prepared after the first complete download.','पहली पूरी डाउनलोडिंग के बाद ऑफलाइन प्रति तैयार होती है।'))}).catch(()=>{});
